-- Учебные синтетические данные проекта IT-Professions (SQLite / DBeaver).
-- Таблицы: instructors -> courses -> groups -> enrollments <- students. Выполнить скриптом (Alt+X).

PRAGMA foreign_keys = OFF;
DROP VIEW IF EXISTS analytics_kpi;
DROP VIEW IF EXISTS analytics_enrollment_details;
DROP TABLE IF EXISTS analytics_enrollments;
DROP TABLE IF EXISTS analytics_students;
DROP TABLE IF EXISTS analytics_groups;
DROP TABLE IF EXISTS analytics_courses;
DROP TABLE IF EXISTS analytics_instructors;

CREATE TABLE "analytics_instructors" ("instructor_id" INTEGER PRIMARY KEY, "full_name" TEXT, "email" TEXT, "specialization" TEXT, "experience_years" INTEGER, "city" TEXT, "hire_date" TEXT);

CREATE TABLE "analytics_courses" ("course_id" INTEGER PRIMARY KEY, "catalog_id" TEXT, "course_title" TEXT, "category" TEXT, "duration" TEXT, "price_kzt" INTEGER, "instructor_id" INTEGER, FOREIGN KEY ("instructor_id") REFERENCES "analytics_instructors"("instructor_id"));

CREATE TABLE "analytics_groups" ("group_id" INTEGER PRIMARY KEY, "course_id" INTEGER, "instructor_id" INTEGER, "schedule_time" TEXT, "start_date" TEXT, "max_students" INTEGER, FOREIGN KEY ("course_id") REFERENCES "analytics_courses"("course_id"), FOREIGN KEY ("instructor_id") REFERENCES "analytics_instructors"("instructor_id"));

CREATE TABLE "analytics_students" ("student_id" INTEGER PRIMARY KEY, "full_name" TEXT, "email" TEXT, "age" INTEGER, "city" TEXT, "reg_date" TEXT, "source" TEXT);

CREATE TABLE "analytics_enrollments" ("enrollment_id" INTEGER PRIMARY KEY, "student_id" INTEGER, "course_id" INTEGER, "group_id" INTEGER, "enroll_date" TEXT, "status" TEXT, "payment_status" TEXT, "discount_pct" INTEGER, "price_paid_kzt" INTEGER, "rating" INTEGER, "city" TEXT, "level" TEXT, FOREIGN KEY ("student_id") REFERENCES "analytics_students"("student_id"), FOREIGN KEY ("course_id") REFERENCES "analytics_courses"("course_id"), FOREIGN KEY ("group_id") REFERENCES "analytics_groups"("group_id"));

CREATE INDEX "idx_analytics_courses_instructor_id" ON "analytics_courses"("instructor_id");
CREATE INDEX "idx_analytics_groups_course_id" ON "analytics_groups"("course_id");
CREATE INDEX "idx_analytics_groups_instructor_id" ON "analytics_groups"("instructor_id");
CREATE INDEX "idx_analytics_enrollments_student_id" ON "analytics_enrollments"("student_id");
CREATE INDEX "idx_analytics_enrollments_course_id" ON "analytics_enrollments"("course_id");
CREATE INDEX "idx_analytics_enrollments_group_id" ON "analytics_enrollments"("group_id");

CREATE VIEW analytics_kpi AS
SELECT COUNT(*)                                                         AS total_enrollments,
       ROUND(100.0 * SUM(status = 'approved') / COUNT(*), 2)            AS approved_share_pct,
       ROUND(AVG(rating), 2)                                            AS avg_rating,
       SUM(price_paid_kzt)                                              AS total_paid_kzt
FROM analytics_enrollments;
CREATE VIEW analytics_enrollment_details AS
SELECT e.enrollment_id, e.enroll_date, substr(e.enroll_date, 1, 7) AS enroll_month,
       s.student_id, s.full_name AS student_name, s.email AS student_email,
       c.course_id, c.course_title, c.category,
       i.instructor_id, i.full_name AS instructor_name,
       g.group_id, g.schedule_time, g.start_date AS group_start_date, g.max_students,
       e.status, e.payment_status, e.discount_pct, e.price_paid_kzt, e.rating, e.city, e.level
FROM analytics_enrollments e
JOIN analytics_students s    ON s.student_id = e.student_id
JOIN analytics_groups g      ON g.group_id = e.group_id
JOIN analytics_courses c     ON c.course_id = g.course_id
JOIN analytics_instructors i ON i.instructor_id = g.instructor_id;
PRAGMA foreign_keys = ON;
